import{_ as a,o as t,c as i,a0 as r}from"./chunks/framework.BMIT1c_r.js";const d=JSON.parse('{"title":"4. Hyperparameter Disentanglement: Paper List","description":"","frontmatter":{},"headers":[],"relativePath":"hyperparameters.md","filePath":"hyperparameters.md"}'),n={name:"hyperparameters.md"};function s(o,e,l,m,c,g){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="_4-hyperparameter-disentanglement-paper-list" tabindex="-1">4. Hyperparameter Disentanglement: Paper List <a class="header-anchor" href="#_4-hyperparameter-disentanglement-paper-list" aria-label="Permalink to &quot;4. Hyperparameter Disentanglement: Paper List&quot;">​</a></h1><blockquote><p>&quot;Optimization hyperparameters in deep learning affect not just the speed and cost of training but also the trajectory that training follows. This in turn affects various properties of the learned network... the theory community has come to realize that hyperparameters can be disentangled and understood.&quot;</p></blockquote><h2 id="a-optimization-hyperparameters-sde-dynamics" tabindex="-1">A. Optimization Hyperparameters &amp; SDE Dynamics <a class="header-anchor" href="#a-optimization-hyperparameters-sde-dynamics" aria-label="Permalink to &quot;A. Optimization Hyperparameters &amp; SDE Dynamics&quot;">​</a></h2><p><em>Focuses on algorithm-level invariances under simultaneous rescaling of step sizes and batch capacities, analyzing stochastic updates as approximations of continuous Stochastic Differential Equations (SDEs).</em></p><ul><li><strong>Goyal et al. [2017]</strong> — <em>Accurate, large minibatch sgd: Training imagenet in 1 hour</em></li><li><strong>Mandt et al. [2017]</strong> — <em>Stochastic gradient descent as approximate bayesian inference</em></li><li><strong>Jastrzebski et al. [2017]</strong> — <em>Three factors influencing minima in sgd</em></li><li><strong>Chaudhari &amp; Soatto [2018]</strong> — <em>Stochastic gradient descent performs variational inference, converges to limit cycles for deep networks</em></li><li><strong>Li et al. [2019]</strong> — <em>Stochastic modified equations and dynamics of stochastic gradient algorithms i: Mathematical foundations</em></li><li><strong>Li et al. [2021b]</strong> — <em>On the validity of modeling sgd with stochastic differential equations (sdes)</em></li><li><strong>Malladi et al. [2022]</strong> — <em>On the sdes and scaling rules for adaptive gradient algorithms</em></li></ul><hr><h2 id="b-resource-tradeoffs-critical-batch-size" tabindex="-1">B. Resource Tradeoffs &amp; Critical Batch Size <a class="header-anchor" href="#b-resource-tradeoffs-critical-batch-size" aria-label="Permalink to &quot;B. Resource Tradeoffs &amp; Critical Batch Size&quot;">​</a></h2><p><em>Focuses on mapping the Pareto frontier balancing serial execution time against total computation cost, defining the optimal critical batch capacity boundaries.</em></p><ul><li><strong>McCandlish et al. [2018]</strong> — <em>An empirical model of large-batch training</em></li><li><strong>Ma et al. [2018]</strong> — <em>The power of interpolation: Understanding the effectiveness of sgd in modern over-parametrized learning</em></li><li><strong>Jain et al. [2018]</strong> — <em>Parallelizing stochastic gradient descent for least squares regression: mini-batching, averaging, and model misspecification</em></li><li><strong>Shallue et al. [2019]</strong> — <em>Measuring the effects of data parallelism on neural network training</em></li></ul><hr><h2 id="c-implicit-regularization-penalized-flows" tabindex="-1">C. Implicit Regularization &amp; Penalized Flows <a class="header-anchor" href="#c-implicit-regularization-penalized-flows" aria-label="Permalink to &quot;C. Implicit Regularization &amp; Penalized Flows&quot;">​</a></h2><p><em>Focuses on the implicit regularization effect of SGD or optimization dynamic, steering parameters toward flat, close and compressible local minima.</em></p><ul><li><strong>Cohen et al. [2025]</strong> — <em>Understanding optimization in deep learning with central flows</em></li><li><strong>Keskar et al. [2016]</strong> — <em>On large-batch training for deep learning: Generalization gap and sharp minima</em></li><li><strong>Jastrzebski et al. [2020]</strong> — <em>The break-even point on optimization trajectories of deep neural networks</em></li><li><strong>Cohen et al. [2021a]</strong> — <em>Gradient descent on neural networks typically occurs at the edge of stability</em></li><li><strong>Blanc et al. [2020]</strong> — <em>Implicit regularization for deep neural networks driven by an ornstein-uhlenbeck like process</em></li><li><strong>Li et al. [2021c]</strong> — <em>What happens after sgd reaches zero loss?-a mathematical framework</em></li><li><strong>Damian et al. [2021]</strong> — <em>Label noise sgd provably prefers flat global minimizers</em></li><li><strong>Wen et al. [2022]</strong> — <em>How does sharpness-aware minimization minimize sharpness?</em></li><li><strong>Li et al. [2025]</strong> — <em>Adam reduces a unique form of sharpness: Theoretical insights near the minimizer manifold</em></li><li><strong>Pesme et al. [2021]</strong> — <em>Implicit bias of sgd for diagonal linear networks: a provable benefit of stochasticity</em></li><li><strong>Chen et al. [2024]</strong> — <em>Stochastic collapse: How gradient noise attracts sgd dynamics towards simpler subnetworks</em></li><li><strong>Barrett &amp; Dherin [2020]</strong> — <em>Implicit gradient regularization</em></li><li><strong>Smith et al. [2021]</strong> — <em>On the origin of implicit regularization in stochastic gradient descent</em></li><li><strong>Schulman &amp; Lab [2025]</strong> — <em>Lora without regret</em></li><li><strong>Catalan-Tatjer et al. [2025]</strong> — <em>Training dynamics impact post-training quantization robustness</em></li><li><strong>Barsbey et al. [2025]</strong> — <em>Large learning rates simultaneously achieve robustness to spurious correlations and compressibility</em></li><li><strong>Chen et al. [2026]</strong> — <em>Nexus: Same Pretraining Loss, Better Downstream Generalization via Common Minima</em></li></ul><hr><h2 id="d-architecture-scaling-invariant-hyperparameter-transfer" tabindex="-1">D. Architecture Scaling &amp; Invariant Hyperparameter Transfer <a class="header-anchor" href="#d-architecture-scaling-invariant-hyperparameter-transfer" aria-label="Permalink to &quot;D. Architecture Scaling &amp; Invariant Hyperparameter Transfer&quot;">​</a></h2><p><em>Focuses on disentangling dimensional coordinates (width, depth) from optimization variables to execute zero-shot hyperparameter predictions across scales.</em></p><ul><li><strong>Yang &amp; Hu [2021]</strong> — <em>Tensor programs iv: Feature learning in infinite-width neural networks</em></li><li><strong>Yang &amp; Littwin [2023]</strong> — <em>Tensor programs ivb: Adaptive optimization in the infinite-width limit</em></li><li><strong>Yang et al. [2022]</strong> — <em>Tensor programs v: Tuning large neural networks via zero-shot hyperparameter transfer</em></li><li><strong>Noci et al. [2024]</strong> — <em>Super consistency of neural network landscapes and learning rate transfer</em></li><li><strong>Ghosh et al. [2025]</strong> — <em>Understanding the mechanisms of fast hyperparameter transfer</em></li><li><strong>Hayou [2025]</strong> — <em>A proof of learning rate transfer under mu p</em></li><li><strong>Yang et al. [2023b]</strong> — <em>Tensor programs vi: Feature learning in infinite-depth neural networks</em></li><li><strong>Bordelon et al. [2023]</strong> — <em>Depthwise hyperparameter transfer in residual networks: Dynamics and scaling limit</em></li><li><strong>Dey et al. [2025]</strong> — <em>Don&#39;t be lazy: Completep enables compute-efficient deep transformers</em></li></ul>',17)])])}const h=a(n,[["render",s]]);export{d as __pageData,h as default};
